import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                        torch::Tensor weight,
                                        c10::optional<torch::Tensor> bias,
                                        int stride, int padding,
                                        int output_padding, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Structural optimization: in addition to CTA-level 3D output tiling with
// shared-memory staging of the reusable input tile (per channel chunk),
// each CTA cooperatively computes CoutTile output channels at once, and
// the per-chunk weight/input tiles are now DOUBLE BUFFERED: while the
// current chunk is being consumed by the compute loop, the next chunk's
// weight and input tiles are cooperatively prefetched into the other
// shared-memory buffer. This overlaps global-memory latency with the
// FMA-heavy compute of the current chunk instead of stalling behind a
// syncthreads() immediately after every load.
template <typename T, int CinChunk, int CoutTile>
__device__ __forceinline__ void load_weight_chunk(
    T* sW_buf, const T* __restrict__ W, int tid, int Threads,
    int cur_chunk, int co_local_base, int CoutPerGroup,
    int ci_start, int ci_base, int64_t sWci, int64_t wKKK, int64_t wKK, int K)
{
  const int wchunk_stride = CinChunk * K * K * K;
  const int w_total = CoutTile * cur_chunk * K * K * K;
  for (int idx = tid; idx < w_total; idx += Threads) {
    int r = idx;
    int kw = r % K; r /= K;
    int kh = r % K; r /= K;
    int kd = r % K; r /= K;
    int ci_local = r % cur_chunk; r /= cur_chunk;
    int co_off = r;
    int co_local = co_local_base + co_off;
    float wv = 0.0f;
    if (co_local < CoutPerGroup) {
      int ci = ci_start + ci_base + ci_local;
      wv = (float)W[(int64_t)ci * sWci + (int64_t)co_local * wKKK +
                    (int64_t)kd * wKK + (int64_t)kh * K + kw];
    }
    sW_buf[co_off * wchunk_stride + ((ci_local * K + kd) * K + kh) * K + kw] = (T)wv;
  }
}
template <typename T, int CinChunk>
__device__ __forceinline__ void load_input_chunk(
    T* sX_buf, const T* __restrict__ Xn, int tid, int Threads,
    int cur_chunk, int ci_start, int ci_base,
    int64_t sXc, int64_t sXd, int64_t sXh,
    int D, int H, int Win, int stride,
    int id_num_min, int ih_num_min, int iw_num_min,
    int ID_TILE, int IH_TILE, int IW_TILE)
{
  const int x_total = cur_chunk * ID_TILE * IH_TILE * IW_TILE;
  for (int idx = tid; idx < x_total; idx += Threads) {
    int r = idx;
    int iw_off = r % IW_TILE; r /= IW_TILE;
    int ih_off = r % IH_TILE; r /= IH_TILE;
    int id_off = r % ID_TILE; r /= ID_TILE;
    int ci_local = r;
    int ci = ci_start + ci_base + ci_local;
    int id_num = id_num_min + id_off;
    int ih_num = ih_num_min + ih_off;
    int iw_num = iw_num_min + iw_off;
    float val = 0.0f;
    bool ok = true;
    int id = 0, ih = 0, iw = 0;
    if (id_num % stride != 0) ok = false;
    else { id = id_num / stride; ok = ok && (id >= 0 && id < D); }
    if (ok) {
      if (ih_num % stride != 0) ok = false;
      else { ih = ih_num / stride; ok = ok && (ih >= 0 && ih < H); }
    }
    if (ok) {
      if (iw_num % stride != 0) ok = false;
      else { iw = iw_num / stride; ok = ok && (iw >= 0 && iw < Win); }
    }
    if (ok) {
      val = (float)Xn[(int64_t)ci * sXc + (int64_t)id * sXd + (int64_t)ih * sXh + iw];
    }
    sX_buf[idx] = (T)val;
  }
}
template <typename T, int TD, int TH, int TW, int CinChunk, int CoutTile>
__global__ void conv_transpose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int K, int stride, int padding,
    int Dout, int Hout, int Wout,
    int CinPerGroup, int CoutPerGroup,
    int num_od_tiles, int num_oh_tiles, int num_ow_tiles,
    int num_co_tiles_per_group)
{
  constexpr int Threads = TD * TH * TW;
  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int co_tile_idx = blockIdx.y;
  const int g = co_tile_idx / num_co_tiles_per_group;
  const int co_tile_in_group = co_tile_idx % num_co_tiles_per_group;
  const int co_local_base = co_tile_in_group * CoutTile;
  const int ci_start  = g * CinPerGroup;
  int tile_flat = blockIdx.x;
  const int ow_tile = tile_flat % num_ow_tiles; tile_flat /= num_ow_tiles;
  const int oh_tile = tile_flat % num_oh_tiles; tile_flat /= num_oh_tiles;
  const int od_tile = tile_flat;
  const int od0 = od_tile * TD;
  const int oh0 = oh_tile * TH;
  const int ow0 = ow_tile * TW;
  const int td = tid / (TH * TW);
  const int rem0 = tid % (TH * TW);
  const int th = rem0 / TW;
  const int tw = rem0 % TW;
  const int od = od0 + td;
  const int oh = oh0 + th;
  const int ow = ow0 + tw;
  const bool out_valid = (od < Dout) && (oh < Hout) && (ow < Wout);
  // Strides (row-major, contiguous NCDHW)
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sXn = (int64_t)Cin * sXc;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  const int64_t sYn = (int64_t)Cout * sYc;
  const T* Xn = X + (int64_t)n * sXn;
  T* Yn = Y + (int64_t)n * sYn;
  // Weight layout: [Cin, CoutPerGroup, K, K, K], contiguous
  const int64_t wKKK = (int64_t)K * K * K;
  const int64_t wKK  = (int64_t)K * K;
  const int64_t sWci = (int64_t)CoutPerGroup * wKKK;
  const int ID_TILE = TD + K - 1;
  const int IH_TILE = TH + K - 1;
  const int IW_TILE = TW + K - 1;
  extern __shared__ unsigned char smem_raw[];
  const size_t sW_buf_elems = (size_t)CoutTile * CinChunk * K * K * K;
  const size_t sX_buf_elems = (size_t)CinChunk * ID_TILE * IH_TILE * IW_TILE;
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  T* sX_ptr = sW_ptr + 2 * sW_buf_elems;
  const int id_num_min = od0 + padding - (K - 1);
  const int ih_num_min = oh0 + padding - (K - 1);
  const int iw_num_min = ow0 + padding - (K - 1);
  float acc[CoutTile];
  #pragma unroll
  for (int co_off = 0; co_off < CoutTile; ++co_off) {
    int co_local = co_local_base + co_off;
    float bval = 0.0f;
    if (co_local < CoutPerGroup) {
      int co = g * CoutPerGroup + co_local;
      if (Bias != nullptr) bval = (float)Bias[co];
    }
    acc[co_off] = bval;
  }
  const int num_chunks = (CinPerGroup + CinChunk - 1) / CinChunk;
  const int wchunk_stride = CinChunk * K * K * K;
  // Prologue: load first chunk into buffer 0
  {
    int ci_base0 = 0;
    int cur_chunk0 = min(CinChunk, CinPerGroup - ci_base0);
    load_weight_chunk<T, CinChunk, CoutTile>(sW_ptr, W, tid, Threads,
        cur_chunk0, co_local_base, CoutPerGroup, ci_start, ci_base0,
        sWci, wKKK, wKK, K);
    load_input_chunk<T, CinChunk>(sX_ptr, Xn, tid, Threads,
        cur_chunk0, ci_start, ci_base0, sXc, sXd, sXh, D, H, Win, stride,
        id_num_min, ih_num_min, iw_num_min, ID_TILE, IH_TILE, IW_TILE);
  }
  __syncthreads();
  for (int chunk = 0; chunk < num_chunks; ++chunk) {
    const int cur_buf = chunk & 1;
    const int nxt_buf = (chunk + 1) & 1;
    const int ci_base = chunk * CinChunk;
    const int cur_chunk = min(CinChunk, CinPerGroup - ci_base);
    // Prefetch next chunk into the other buffer while we compute on the
    // current buffer below; this overlaps global-memory latency with FMAs.
    if (chunk + 1 < num_chunks) {
      const int ci_base_nxt = (chunk + 1) * CinChunk;
      const int cur_chunk_nxt = min(CinChunk, CinPerGroup - ci_base_nxt);
      T* sW_nxt = sW_ptr + nxt_buf * sW_buf_elems;
      T* sX_nxt = sX_ptr + nxt_buf * sX_buf_elems;
      load_weight_chunk<T, CinChunk, CoutTile>(sW_nxt, W, tid, Threads,
          cur_chunk_nxt, co_local_base, CoutPerGroup, ci_start, ci_base_nxt,
          sWci, wKKK, wKK, K);
      load_input_chunk<T, CinChunk>(sX_nxt, Xn, tid, Threads,
          cur_chunk_nxt, ci_start, ci_base_nxt, sXc, sXd, sXh, D, H, Win, stride,
          id_num_min, ih_num_min, iw_num_min, ID_TILE, IH_TILE, IW_TILE);
    }
    if (out_valid) {
      T* sW_cur = sW_ptr + cur_buf * sW_buf_elems;
      T* sX_cur = sX_ptr + cur_buf * sX_buf_elems;
      #pragma unroll
      for (int kd = 0; kd < K; ++kd) {
        int id_off = td - kd + (K - 1);
        #pragma unroll
        for (int kh = 0; kh < K; ++kh) {
          int ih_off = th - kh + (K - 1);
          #pragma unroll
          for (int kw = 0; kw < K; ++kw) {
            int iw_off = tw - kw + (K - 1);
            for (int ci_local = 0; ci_local < cur_chunk; ++ci_local) {
              float xval = (float)sX_cur[((ci_local * ID_TILE + id_off) * IH_TILE + ih_off) * IW_TILE + iw_off];
              #pragma unroll
              for (int co_off = 0; co_off < CoutTile; ++co_off) {
                float wval = (float)sW_cur[co_off * wchunk_stride + ((ci_local * K + kd) * K + kh) * K + kw];
                acc[co_off] += xval * wval;
              }
            }
          }
        }
      }
    }
    // Single barrier: guarantees the prefetch into nxt_buf has completed
    // (needed before it becomes cur_buf next iteration) AND that the
    // compute reading cur_buf has finished (needed before it gets
    // overwritten as nxt_buf two iterations from now).
    __syncthreads();
  }
  if (out_valid) {
    #pragma unroll
    for (int co_off = 0; co_off < CoutTile; ++co_off) {
      int co_local = co_local_base + co_off;
      if (co_local < CoutPerGroup) {
        int co = g * CoutPerGroup + co_local;
        Yn[(int64_t)co * sYc + (int64_t)od * sYd + (int64_t)oh * sYh + ow] = static_cast<T>(acc[co_off]);
      }
    }
  }
}
torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                        torch::Tensor weight,
                                        c10::optional<torch::Tensor> bias,
                                        int stride, int padding,
                                        int output_padding, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N,C,D,H,W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout/groups, K,K,K]");
  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  int64_t N   = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t D   = x_c.size(2);
  int64_t H   = x_c.size(3);
  int64_t Win = x_c.size(4);
  TORCH_CHECK(w_c.size(0) == Cin, "weight.size(0) must equal Cin");
  int64_t CoutPerGroup = w_c.size(1);
  int64_t K = w_c.size(2);
  TORCH_CHECK(w_c.size(3) == K && w_c.size(4) == K, "kernel must be cubic");
  int64_t Cout = CoutPerGroup * groups;
  int64_t CinPerGroup = Cin / groups;
  TORCH_CHECK(CinPerGroup * groups == Cin, "Cin must be divisible by groups");
  int64_t Dout = (D - 1) * stride - 2 * padding + K + output_padding;
  int64_t Hout = (H - 1) * stride - 2 * padding + K + output_padding;
  int64_t Wout = (Win - 1) * stride - 2 * padding + K + output_padding;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());
  constexpr int TD = 4;
  constexpr int TH = 4;
  constexpr int TW = 8;
  constexpr int Threads = TD * TH * TW;
  constexpr int CinChunk = 8;
  constexpr int CoutTile = 32;
  int num_od_tiles = (int)((Dout + TD - 1) / TD);
  int num_oh_tiles = (int)((Hout + TH - 1) / TH);
  int num_ow_tiles = (int)((Wout + TW - 1) / TW);
  int num_co_tiles_per_group = (int)((CoutPerGroup + CoutTile - 1) / CoutTile);
  dim3 block(Threads);
  dim3 grid(
      (unsigned)(num_od_tiles * num_oh_tiles * num_ow_tiles),
      (unsigned)(groups * num_co_tiles_per_group),
      (unsigned)N
  );
  int ID_TILE = (int)K + TD - 1;
  int IH_TILE = (int)K + TH - 1;
  int IW_TILE = (int)K + TW - 1;
  // Double-buffered shared memory: two copies of the per-chunk weight
  // tile and two copies of the per-chunk input tile, enabling the
  // kernel to prefetch chunk (i+1) while computing on chunk i.
  size_t smem_bytes = 2 * (size_t)(CoutTile * CinChunk * (int)K * (int)K * (int)K +
                                CinChunk * ID_TILE * IH_TILE * IW_TILE) * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  auto kernel_ptr = conv_transpose3d_kernel<float, TD, TH, TW, CinChunk, CoutTile>;
  auto attr_err = cudaFuncSetAttribute(kernel_ptr, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
  TORCH_CHECK(attr_err == cudaSuccess, "cudaFuncSetAttribute failed (requested ", smem_bytes,
              " bytes dynamic shared mem): ", cudaGetErrorString(attr_err));
  kernel_ptr<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)K, (int)stride, (int)padding,
      (int)Dout, (int)Hout, (int)Wout,
      (int)CinPerGroup, (int)CoutPerGroup,
      num_od_tiles, num_oh_tiles, num_ow_tiles,
      num_co_tiles_per_group
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution with square input and square kernel,
    implemented with a custom CuTe-based CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.output_padding = int(output_padding)
        self.groups = int(groups)

        Cin = self.in_channels
        Cout = self.out_channels
        K = self.kernel_size
        assert Cin % self.groups == 0
        assert Cout % self.groups == 0

        # Weight layout matches nn.ConvTranspose3d: [Cin, Cout/groups, K, K, K]
        self.weight = nn.Parameter(torch.empty(Cin, Cout // self.groups, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(Cout))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv_transpose3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.output_padding),
            int(self.groups),
        )

